import React, { useRef, useEffect, useState } from 'react';
import { Message } from '../types';
import { ChatMessage } from './ChatMessage';
import { ChatInput } from './ChatInput';

interface ChatContainerProps {
  messages: Message[];
  isLoading: boolean;
  inputLocked?: boolean;
  onSend: (question: string, description: string) => void;
  onSimilarQuestionClick: (question: string) => void;
  onClearHistory: () => void;
  exportMenu?: React.ReactNode;
  quickPrompts?: string[];
}

export const ChatContainer: React.FC<ChatContainerProps> = ({
  messages,
  isLoading,
  onSend,
  onSimilarQuestionClick,
  onClearHistory,
  exportMenu,
  quickPrompts = []
}) => {
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messagesContainerRef = useRef<HTMLDivElement>(null);
  const [loadingSec, setLoadingSec] = useState(0);

  const userMessageCount = messages.filter((m) => m.type === 'user').length;
  const showQuickPrompts = userMessageCount === 0 && !isLoading && quickPrompts.length > 0;

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isLoading]);

  useEffect(() => {
    if (!isLoading) {
      setLoadingSec(0);
      return;
    }
    const t0 = Date.now();
    const id = window.setInterval(() => {
      setLoadingSec(Math.floor((Date.now() - t0) / 1000));
    }, 1000);
    return () => window.clearInterval(id);
  }, [isLoading]);

  const handleClear = () => {
    if (window.confirm('确定要清空所有对话记录吗？')) {
      onClearHistory();
    }
  };

  return (
    <div className="chat-container">
      <div className="chat-header">
        <div className="header-content">
          <h2>💬 心理港湾</h2>
          <p>我在这里倾听您的心声</p>
        </div>
        <div className="header-actions">
          {exportMenu}
          <button type="button" className="action-btn" onClick={handleClear}>
            🗑️ 清空
          </button>
        </div>
      </div>

      <div className="chat-messages" ref={messagesContainerRef}>
        {showQuickPrompts && (
          <div className="chat-welcome">
            <p className="chat-welcome-title">可以从这些话题开始：</p>
            <div className="quick-prompts">
              {quickPrompts.map((q) => (
                <button
                  key={q}
                  type="button"
                  className="quick-prompt-chip"
                  onClick={() => onSend(q, '')}
                >
                  {q}
                </button>
              ))}
            </div>
          </div>
        )}

        {messages.map((message, index) => {
          const userQuery =
            message.type === 'bot'
              ? [...messages.slice(0, index)].reverse().find((m) => m.type === 'user')?.content
              : undefined;
          return (
            <ChatMessage
              key={message.id}
              message={message}
              knowledgeSources={message.knowledgeSources}
              userQuery={userQuery}
              onSimilarQuestionClick={onSimilarQuestionClick}
            />
          );
        })}

        {isLoading && (
          <div className="loading chat-loading">
            <div className="typing-indicator" aria-hidden="true">
              <span />
              <span />
              <span />
            </div>
            <p>大模型正在生成回复…{loadingSec > 0 ? `（已等待 ${loadingSec} 秒）` : ''}</p>
            <p className="chat-loading-hint">
              {loadingSec < 8
                ? '首次调用约需 15～60 秒，请稍候；详细报告与画像在后台生成。'
                : '仍在生成中，可先浏览上方内容；若超过 2 分钟无响应请刷新后重试。'}
            </p>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      <ChatInput onSend={onSend} disabled={isLoading} />
    </div>
  );
};
